from author import *

CO = "tgat2.language.communication."
R = "tgat2.language.reading."
SRC = ["ผังการสอบ TGAT2 จาก mytcas.com (ความสามารถทางภาษา)", "บทอ่านเรียบเรียงขึ้นใหม่เพื่อการฝึก"]


def an(a, b, c):
    return f"{a} : {b}  ::  {c} : ?"


def analogy_lesson(tid, title, subtitle, rel_md, ex, pit, chk, prereq, nxt=None):
    return lesson(tid, title, subtitle,
        objectives=["ระบุความสัมพันธ์ของคู่คำแรกเป็นประโยค", "ใช้ประโยคเดียวกันทดสอบคู่ที่สอง", "แยกความสัมพันธ์ที่คล้ายกันออกจากกัน"],
        minutes=20, prereq=prereq, nxt=nxt or [],
        blocks=[
            hook("อุปมาอุปไมยคำไม่ได้วัดว่ารู้ศัพท์มากแค่ไหน แต่วัดว่าเห็น **ความสัมพันธ์** ระหว่างคำได้ชัดแค่ไหน"),
            concept("ความสัมพันธ์ในหัวข้อนี้", rel_md),
            technique("ทำประโยคเชื่อม", "ทุกข้ออุปมาอุปไมยคำ", "ถ้าประโยคเชื่อมใช้ได้กับหลายตัวเลือก ให้ทำประโยคให้เฉพาะเจาะจงขึ้น",
                      "แต่งประโยคหนึ่งประโยคที่เชื่อมคำคู่แรก เช่น \"A เป็นชนิดหนึ่งของ B\" แล้วแทนคำคู่ที่สองลงในประโยคเดียวกัน ตัวเลือกที่อ่านได้ความคือคำตอบ",
                      tip="ประโยคเดียว ใช้ได้ทั้งสองคู่"),
            example("ตัวอย่างที่ 1", ex[0], ex[1], ex[2]),
            pitfall(*pit),
            summary("แต่งประโยคเชื่อมคู่แรกก่อนดูตัวเลือก", "ใช้ประโยคเดียวกันกับคู่ที่สอง", "ระวังตัวเลือกที่เกี่ยวข้องแต่ความสัมพันธ์ต่างแบบ", "ลำดับคำต้องตรงกัน A:B ไม่ใช่ B:A"),
            check(*chk),
        ],
        patterns=["A : B :: C : ?", "คู่ใดมีความสัมพันธ์เหมือนคู่ที่ให้"],
        sources=SRC)


